const { readFileSync } = require('fs');

function main() {
  const data = readFileSync(0, 'utf8').split(/\s+/).filter(s => s.length > 0);
  let idx = 0;
  const N = parseInt(data[idx++], 10);
  const C = parseInt(data[idx++], 10);
  const infected = new Uint8Array(N + 1);

  for (let i = 0; i < C; i++) {
    const P = parseInt(data[idx++], 10);
    const I = parseInt(data[idx++], 10);
    for (let j = 0; j < I; j++) {
      const X = parseInt(data[idx++], 10);
      infected[X] = 1;
    }
  }

  const out = [];
  for (let p = 1; p <= N; p++) {
    if (!infected[p]) out.push(p);
  }
  process.stdout.write(out.join('\n') + '\n');
}

main();
